const fs=require('fs');const puppeteer=require('puppeteer-core');const vps=[{name:'768x1024',width:768,height:1024},{name:'390x844',width:390,height:844},{name:'360x800',width:360,height:800}];const sleep=ms=>new Promise(r=>setTimeout(r,ms));(async()=>{const b=await puppeteer.launch({headless:true,executablePath:process.env.CHROME,args:['--no-sandbox','--disable-dev-shm-usage']});fs.mkdirSync('gate-a-nav-steady',{recursive:true});const out={cases:{},failures:[]};for(const vp of vps){const p=await b.newPage();await p.setViewport({width:vp.width,height:vp.height});await p.goto('http://127.0.0.1:8000/index.html',{waitUntil:'load'});await p.click('.menu-toggle');await sleep(450);const d=await p.evaluate(()=>{const n=document.querySelector('#primary-nav'),h=document.querySelector('.site-header'),m=document.querySelector('main'),f=document.querySelector('footer');const rr=e=>{const r=e.getBoundingClientRect();return{left:r.left,top:r.top,right:r.right,bottom:r.bottom,width:r.width,height:r.height}};const ns=getComputedStyle(n),hs=getComputedStyle(h);return{viewport:{w:innerWidth,h:innerHeight},nav:rr(n),navOpacity:ns.opacity,navTransform:ns.transform,navVisibility:ns.visibility,navPosition:ns.position,navOverflowY:ns.overflowY,headerBackdrop:hs.backdropFilter,links:[...n.querySelectorAll('a[href]')].map(a=>({text:a.textContent.trim(),rect:rr(a)})),mainInert:m.inert,footerInert:f.inert}});out.cases[vp.name]=d;const pass=Math.abs(d.nav.left)<.5&&Math.abs(d.nav.top)<.5&&Math.abs(d.nav.width-vp.width)<.5&&Math.abs(d.nav.height-vp.height)<.5&&d.navOpacity==='1'&&d.navTransform==='none'&&d.links.length===6&&d.links.every(x=>x.rect.top>=0&&x.rect.bottom<=vp.height)&&d.mainInert&&d.footerInert;if(!pass)out.failures.push({viewport:vp.name,data:d});await p.screenshot({path:`gate-a-nav-steady/nav-${vp.name}.png`});await p.close()}fs.writeFileSync('gate-a-nav-steady/report.json',JSON.stringify(out,null,2));console.log(JSON.stringify(out,null,2));await b.close();if(out.failures.length)process.exit(2)})().catch(e=>{console.error(e);process.exit(1)});
